import { createRoot } from 'react-dom/client';
import { Provider } from 'react-redux';
import { ThemeProvider } from '../../src/context/ThemeProvider';
import { MemoryRouter, Link, Routes, Route } from 'react-router-dom';
import { store } from '../../src/store';
import { loginSuccess } from '../../src/store/slices/authSlice';
import { MarketingTracking } from '../../src/pages/MarketingTracking';
import { BillingPanel } from '../../src/pages/settings/BillingPanel';
import { defaultSettings } from '../../src/pages/settings/data';
import { PaymentMethodsPanel } from '../../src/pages/settings/PaymentMethodsPanel';
import { GetAppButton } from '../../src/components/layout/GetAppButton';
import { TrackingRuntime } from '../../src/backend/marketingTracking';
import { CheckoutScreen } from '../../src/pages/commerce/CheckoutScreen';
import { newProduct } from '../../src/pages/commerce/model';
import { LandingPage } from '../../src/pages/landing/LandingPage';
import '../../src/i18n/i18n';
import '../../src/index.css';
import '../../src/layout-shell.css';
import '../../src/global-controls.css';
import '../../src/theme-surfaces.css';
import '../../src/theme-controls.css';
import '../../src/module-updates.css';
import '../../src/pages/commerce/commerce-enhancements.css';
const product = newProduct(); product.name = 'Feature Test'; product.id = 'test-product';
const login = (role: 'USER' | 'ADMIN' | 'SUPER_ADMIN') => store.dispatch(loginSuccess({ user: { id: 'feature-user', name: 'Feature User', email: 'features@example.com' }, role, tenant: { id: 'features', name: 'Feature Test' }, token: 'test' }));
if (!new URLSearchParams(location.search).has('anonymous')) login('ADMIN'); (window as any).__writes = [];
createRoot(document.getElementById('root')!).render(<Provider store={store}><ThemeProvider><MemoryRouter initialEntries={[new URLSearchParams(location.search).get('view') === 'landing' ? '/landing' : '/']}><TrackingRuntime/><nav className="flex flex-wrap items-center gap-3 p-3"><GetAppButton/><Link to="/">Tracking</Link><Link to="/billing">Billing</Link><Link to="/checkout">Checkout</Link><Link to="/billing-tabs">Billing tabs</Link><button onClick={() => login('USER')}>User role</button><button onClick={() => login('SUPER_ADMIN')}>Superadmin role</button></nav><div className="p-4"><Routes><Route path="/" element={<MarketingTracking/>}/><Route path="/billing" element={<PaymentMethodsPanel/>}/><Route path="/billing-tabs" element={<div className="st-workspace"><BillingPanel data={defaultSettings()} refresh={async()=>{}} saveLocal={async()=>{}}/></div>}/><Route path="/checkout" element={<CheckoutScreen product={product}/>}/><Route path="/landing" element={<LandingPage/>}/></Routes></div></MemoryRouter></ThemeProvider></Provider>);
